import React from 'react';
import { Agent } from '@/types';
import { User, ExternalLink, Cpu } from 'lucide-react';
import { motion } from 'framer-motion';

interface AgentCardProps {
    agent: Agent;
    onClick?: (agent: Agent) => void;
}

export function AgentCard({ agent, onClick }: AgentCardProps) {
    return (
        <motion.div
            whileHover={{ y: -5, scale: 1.02 }}
            className="p-6 clay-card flex flex-col h-full bg-white/40 backdrop-blur-md transition-all duration-300 group cursor-pointer"
            onClick={() => onClick?.(agent)}
        >
            <div className="flex items-start justify-between mb-4">
                <div className="flex items-center gap-3">
                    <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-blue-400 to-indigo-500 flex items-center justify-center text-white shadow-lg">
                        <Cpu className="w-6 h-6" />
                    </div>
                    <div>
                        <h3 className="font-bold text-gray-800 text-lg leading-tight group-hover:text-blue-600 transition-colors">
                            {agent.name}
                        </h3>
                        <p className="text-xs text-blue-500 font-medium uppercase tracking-wider">
                            {agent.role || "Autonomous Agent"}
                        </p>
                    </div>
                </div>
                <div className={`w-3 h-3 rounded-full shadow-inner ${agent.status === 'online' ? 'bg-green-400' : 'bg-gray-300'}`} title={agent.status || 'Offline'} />
            </div>

            <p className="text-gray-600 text-sm mb-6 line-clamp-3 leading-relaxed flex-grow">
                {agent.description}
            </p>

            <div className="mt-auto">
                <button className="w-full py-2.5 rounded-xl bg-white/50 hover:bg-white text-blue-600 border border-blue-100 font-semibold text-sm transition-all duration-200 shadow-sm hover:shadow active:scale-95 flex items-center justify-center gap-2">
                    View Profile
                    <ExternalLink className="w-3 h-3" />
                </button>
            </div>
        </motion.div>
    );
}

import React from 'react';
import { Agent } from '@/types';
import { cn } from '@/lib/utils';
import { User, Activity, Circle } from 'lucide-react';

interface AgentListProps {
    agents: Agent[];
    currentAgent: Agent | null;
    onSelectAgent: (agent: Agent) => void;
    loading: boolean;
}

export function AgentList({ agents, currentAgent, onSelectAgent, loading }: AgentListProps) {
    if (loading) {
        return (
            <div className="p-4 space-y-3">
                {[1, 2, 3].map((i) => (
                    <div key={i} className="h-16 bg-muted/50 animate-pulse rounded-lg" />
                ))}
            </div>
        )
    }

    if (agents.length === 0) {
        return (
            <div className="p-8 text-center text-muted-foreground border border-dashed border-border m-4 rounded-xl bg-muted/20">
                <User className="w-10 h-10 mx-auto mb-2 opacity-50" />
                <p className="text-sm">No active agents found.</p>
            </div>
        )
    }

    return (
        <div className="flex flex-col gap-1 p-2">
            {agents.map((agent) => (
                <button
                    key={agent.url}
                    onClick={() => onSelectAgent(agent)}
                    className={cn(
                        "flex items-start gap-3 p-3 text-left transition-all duration-200 rounded-lg group",
                        currentAgent?.url === agent.url
                            ? "bg-primary/10 text-foreground shadow-sm ring-1 ring-primary/20"
                            : "hover:bg-muted text-muted-foreground hover:text-foreground"
                    )}
                >
                    <div className={cn(
                        "w-8 h-8 rounded-full flex items-center justify-center shrink-0 border transition-colors",
                        currentAgent?.url === agent.url ? "bg-primary text-primary-foreground border-primary" : "bg-background border-border"
                    )}>
                        <span className="text-xs font-semibold">{agent.name.substring(0, 2).toUpperCase()}</span>
                    </div>

                    <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between mb-0.5">
                            <span className={cn("text-sm font-medium truncate", currentAgent?.url === agent.url && "text-primary")}>
                                {agent.name}
                            </span>
                            {currentAgent?.url === agent.url && (
                                <span className="flex h-2 w-2 rounded-full bg-green-500" />
                            )}
                        </div>
                        <p className="text-xs truncate opacity-80">
                            {agent.description}
                        </p>
                    </div>
                </button>
            ))}
        </div>
    );
}

import React, { useState, useRef, useEffect } from 'react';
import { Agent, Message } from '@/types';
import { Send, Bot, User, Sparkles } from 'lucide-react';
import { cn } from '@/lib/utils';
import { motion, AnimatePresence } from 'framer-motion';

interface ChatInterfaceProps {
    agent: Agent;
}

export function ChatInterface({ agent }: ChatInterfaceProps) {
    const [messages, setMessages] = useState<Message[]>([
        {
            role: 'system',
            parts: [{ text: `Connected to ${agent.name}\n${agent.description}` }],
            timestamp: new Date().toISOString()
        }
    ]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        // Reset chat when agent changes
        setMessages([
            {
                role: 'system',
                parts: [{ text: `Connected to ${agent.name}\n${agent.description}` }],
                timestamp: new Date().toISOString()
            }
        ]);
        setInput('');
    }, [agent.url]);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);

    // Auto-resize textarea
    useEffect(() => {
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
            textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
        }
    }, [input]);

    const sendMessage = async () => {
        if (!input.trim() || isLoading) return;

        const userMsg: Message = {
            role: 'user',
            parts: [{ text: input.trim() }],
            timestamp: new Date().toISOString()
        };

        setMessages(prev => [...prev, userMsg]);
        setInput('');
        setIsLoading(true);

        // Reset height
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
        }

        try {
            const payload = {
                jsonrpc: "2.0",
                id: Math.random().toString(36).substring(7),
                method: "tasks/send",
                params: {
                    id: Math.random().toString(36).substring(7),
                    sessionId: null,
                    message: {
                        role: "user",
                        parts: [{ text: userMsg.parts[0].text }],
                        timestamp: userMsg.timestamp
                    }
                }
            };

            const res = await fetch(agent.url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            const data = await res.json();

            if (data.result) {
                const history = data.result.history;
                const lastMsg = history[history.length - 1];
                if (lastMsg && lastMsg.parts) {
                    setMessages(prev => [...prev, {
                        role: 'agent',
                        parts: [{ text: lastMsg.parts[0].text }],
                        timestamp: new Date().toISOString()
                    }]);
                }
            } else if (data.error) {
                throw new Error(data.error.message || JSON.stringify(data.error));
            }

        } catch (error: unknown) {
            const errorMessage = error instanceof Error ? error.message : "Unknown error";
            setMessages(prev => [...prev, {
                role: 'system',
                parts: [{ text: `Error: ${errorMessage}` }],
                timestamp: new Date().toISOString()
            }]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage();
        }
    };

    return (
        <div className="flex flex-col h-full bg-background border border-border rounded-xl shadow-sm overflow-hidden relative">

            {/* Header */}
            <div className="flex items-center justify-between p-4 border-b border-border bg-card z-10">
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-lg bg-primary/10 text-primary`}>
                        <Bot className="w-5 h-5" />
                    </div>
                    <div>
                        <h3 className="font-semibold text-base text-foreground">{agent.name}</h3>
                        <div className="flex items-center gap-1.5">
                            <span className="block w-2 h-2 bg-green-500 rounded-full" />
                            <p className="text-xs text-muted-foreground">Active</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Messages */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 z-10 bg-muted/30">
                <AnimatePresence initial={false}>
                    {messages.map((msg, i) => (
                        <motion.div
                            key={i}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className={cn(
                                "flex gap-3 max-w-[85%]",
                                msg.role === 'user' ? "ml-auto flex-row-reverse" : "mr-auto"
                            )}
                        >
                            <div className={cn(
                                "w-8 h-8 rounded-full flex items-center justify-center shrink-0 border text-xs font-bold shadow-sm mt-1",
                                msg.role === 'user' ? "bg-primary text-primary-foreground border-primary" :
                                    msg.role === 'system' ? "bg-amber-100 text-amber-700 border-amber-200 dark:bg-amber-900/30 dark:text-amber-400 dark:border-amber-800" :
                                        "bg-white text-zinc-700 border-zinc-200 dark:bg-zinc-800 dark:text-zinc-300 dark:border-zinc-700"
                            )}>
                                {msg.role === 'user' ? <User className="w-4 h-4" /> :
                                    msg.role === 'system' ? <Sparkles className="w-4 h-4" /> :
                                        <span className="text-[10px]">{agent.name.substring(0, 2).toUpperCase()}</span>}
                            </div>

                            <div className="flex flex-col gap-1 min-w-0">
                                <div className={cn(
                                    "px-4 py-2.5 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap shadow-sm break-words",
                                    msg.role === 'user' ? "bg-primary text-primary-foreground rounded-tr-sm" :
                                        msg.role === 'system' ? "bg-amber-50 text-amber-900 border border-amber-100 dark:bg-amber-950/30 dark:text-amber-200 dark:border-amber-900/50 text-center w-full" :
                                            "bg-card border border-border text-foreground rounded-tl-sm"
                                )}>
                                    {msg.parts[0].text}
                                </div>
                                {msg.timestamp && (
                                    <span className={cn(
                                        "text-[10px] text-muted-foreground opacity-70",
                                        msg.role === 'user' ? "text-right" : "text-left"
                                    )}>
                                        {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </span>
                                )}
                            </div>
                        </motion.div>
                    ))}
                    {isLoading && (
                        <motion.div
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            className="flex gap-3 mr-auto"
                        >
                            <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 border bg-white border-zinc-200 dark:bg-zinc-800 dark:border-zinc-700 mt-1">
                                <Bot className="w-4 h-4 text-muted-foreground" />
                            </div>
                            <div className="px-4 py-3 rounded-2xl rounded-tl-sm bg-card border border-border text-foreground shadow-sm flex items-center gap-1.5">
                                <span className="w-1.5 h-1.5 bg-muted-foreground/40 rounded-full animate-bounce delay-0" />
                                <span className="w-1.5 h-1.5 bg-muted-foreground/40 rounded-full animate-bounce delay-150" />
                                <span className="w-1.5 h-1.5 bg-muted-foreground/40 rounded-full animate-bounce delay-300" />
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Input */}
            <div className="p-4 bg-card border-t border-border z-10">
                <div className="relative flex items-end gap-2 bg-muted/50 border border-input rounded-xl focus-within:ring-2 focus-within:ring-primary/20 focus-within:border-primary transition-all p-2">
                    <textarea
                        ref={textareaRef}
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder={`Message ${agent.name}...`}
                        className="w-full bg-transparent border-none focus:ring-0 text-sm placeholder:text-muted-foreground resize-none max-h-32 min-h-[24px] py-1 px-2"
                        rows={1}
                    />
                    <button
                        onClick={sendMessage}
                        disabled={!input.trim() || isLoading}
                        className="p-2 rounded-lg bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors shrink-0 mb-px"
                    >
                        <Send className="w-4 h-4" />
                    </button>
                </div>
                <p className="text-[10px] text-center text-muted-foreground mt-2 opacity-60">
                    Press <strong>Enter</strong> to send, <strong>Shift + Enter</strong> for new line
                </p>
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import { X, Plus, Save } from 'lucide-react';
import { cn } from '@/lib/utils';
import { CreateAgentPayload } from '@/types';

interface CreateAgentModalProps {
    isOpen: boolean;
    onClose: () => void;
    onCreate: (agent: CreateAgentPayload) => Promise<void>;
}

export function CreateAgentModal({ isOpen, onClose, onCreate }: CreateAgentModalProps) {
    const [formData, setFormData] = useState({ name: '', description: '', role: '' });
    const [isSubmitting, setIsSubmitting] = useState(false);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);
        try {
            await onCreate(formData);
            onClose();
            setFormData({ name: '', description: '', role: '' });
        } catch (error) {
            console.error("Failed to create agent", error);
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
            <div className="relative w-full max-w-lg bg-background border border-border rounded-xl shadow-xl overflow-hidden animate-in zoom-in-95 duration-200">

                {/* Header */}
                <div className="flex items-center justify-between p-6 border-b border-border bg-muted/20">
                    <div>
                        <h2 className="text-lg font-semibold text-foreground">New Agent</h2>
                        <p className="text-sm text-muted-foreground">Deploy a new AI agent to the network.</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-muted rounded-full transition-colors text-muted-foreground">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-foreground">Name</label>
                        <input
                            type="text"
                            required
                            value={formData.name}
                            onChange={e => setFormData({ ...formData, name: e.target.value })}
                            className="w-full bg-background border border-input rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all placeholder:text-muted-foreground/50"
                            placeholder="e.g. Research Assistant"
                        />
                    </div>

                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-foreground">Description</label>
                        <input
                            type="text"
                            required
                            value={formData.description}
                            onChange={e => setFormData({ ...formData, description: e.target.value })}
                            className="w-full bg-background border border-input rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all placeholder:text-muted-foreground/50"
                            placeholder="What does this agent do?"
                        />
                    </div>

                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-foreground">System Prompt</label>
                        <textarea
                            required
                            value={formData.role}
                            onChange={e => setFormData({ ...formData, role: e.target.value })}
                            className="w-full bg-background border border-input rounded-md px-3 py-2 text-sm h-32 resize-none focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all placeholder:text-muted-foreground/50 leading-relaxed"
                            placeholder="You are a helpful assistant..."
                        />
                        <p className="text-xs text-muted-foreground">The initial instructions that define the agent&apos;s behavior.</p>
                    </div>

                    <div className="pt-4 flex justify-end gap-3 border-t border-border mt-6">
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-4 py-2 text-sm font-medium text-muted-foreground hover:bg-muted hover:text-foreground rounded-md transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground hover:bg-primary/90 rounded-md text-sm font-medium transition-all shadow-sm disabled:opacity-70 disabled:cursor-not-allowed"
                        >
                            {isSubmitting ? (
                                <>
                                    <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    Deploying...
                                </>
                            ) : (
                                <>
                                    Deplay Agent
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}
